function routeDeviceOptions(sel,r,step){let devs=allLogicalDevices().slice().sort((a,b)=>String(categoryLabel(a.category)).localeCompare(String(categoryLabel(b.category)))||String(a.name||"").localeCompare(String(b.name||""))),known=devs.some(d=>d.key===sel),html=!known&&sel?`<option value="${esc(sel)}" selected>${sysText("Nicht verfÃ¼gbar","Unavailable")}</option>`:"";let allowed=devs.filter(d=>d.key===sel||routeCandidateAllowed(r,step,d));return html+allowed.map(d=>`<option value="${esc(d.key)}" ${d.key===sel?"selected":""}>${esc(d.name||categoryLabel(d.category))} Â· ${esc(categoryLabel(d.category))}${d.controllerName?` Â· ${esc(d.controllerName)}`:""}${d.online?"":` Â· ${sysText("OFFLINE","OFFLINE")}`}</option>`).join("")}
function routeBuilderHtml(r,i){let keys=Array.isArray(r.deviceKeys)?r.deviceKeys:[];if(!keys.length)return `<div class="route-empty simple-route-empty">${sysText("Noch leer. Mit â€+ Anlagenteilâ€œ kannst du mit jedem vorhandenen GerÃ¤t beginnen.","Empty. Use â€œ+ deviceâ€ to start with any existing device.")}</div>`;return `<div class="simple-route-builder">${keys.map((k,j)=>{let d=deviceForKey(k);return `${j?'<span class="simple-route-arrow">â†’</span>':''}<div class="simple-route-step"><small>${esc(d?categoryLabel(d.category):sysText("Anlagenteil","Device"))}</small><select data-route="${i}" data-step="${j}">${routeDeviceOptions(k,r,j)}</select><div class="simple-step-actions"><button class=secondary data-stepup="${i},${j}" ${j===0?"disabled":""} title="${sysText("Nach links","Move left")}">â†</button><button class=secondary data-stepdown="${i},${j}" ${j===keys.length-1?"disabled":""} title="${sysText("Nach rechts","Move right")}">â†’</button><button class=danger data-delstep="${i},${j}" title="${sysText("Aus Signalweg entfernen","Remove from signal path")}">Ã—</button></div></div>`}).join("")}</div>`}
function routesHtml(){if(!Array.isArray(shared.routes))shared.routes=[];let routes=shared.routes.map((r,i)=>{let topo=routeTopologyState(r),bs=routeBandState(r),topology=topo.kind==="ok"?`<div class="route-band-ok">âœ“ ${sysText("Reihenfolge technisch plausibel","Order technically plausible")}</div>`:topo.kind==="incomplete"?`<div class="route-band-unknown">â“˜ ${esc(topo.message)}</div>`:`<div class="route-band-warn">â›” ${esc(topo.message)}</div>`,status=bs.kind==="ok"?`<div class="route-band-ok">âœ“ ${t("routeBandOk")}: ${esc(bs.bands.join(", "))}</div>`:bs.kind==="conflict"?`<div class="route-band-warn">âš  ${t("routeBandConflict")}</div>`:`<div class="route-band-unknown">â“˜ ${t("routeBandUnknown")}</div>`;let override=bs.kind==="conflict"?`<label class="row route-override"><input type=checkbox data-route="${i}" data-rk=bandOverride ${r.bandOverride?"checked":""}> ${t("manualOverride")}</label>${r.bandOverride?`<label>${t("overrideReason")}<input data-route="${i}" data-rk=overrideNote value="${esc(r.overrideNote||"")}"></label>`:""}`:(r.bandOverride?`<div class="small">${sysText("Band-Override ist gespeichert, wird fÃ¼r diesen aktuell plausiblen Weg aber nicht benÃ¶tigt.","A band override is stored but is not needed for this currently plausible path.")}</div>`:"");return `<div class="card route-card simple-route-card" style="--route-color:${esc(r.color||"#3f8fd2")}"><div class="simple-route-head"><label class="simple-active"><input type=checkbox data-route="${i}" data-rk=enabled ${r.enabled!==false?"checked":""}> ${t("active")}</label><label>${t("routeName")}<input data-route="${i}" data-rk=label value="${esc(r.label||"")}"></label><label class="route-color-label">${t("routeColor")}<input data-route="${i}" data-rk=color type=color value="${esc(r.color||"#3f8fd2")}"></label></div><div class="simple-route-title"><b>${sysText("Signalweg","Signal path")}</b><span>${sysText("Die Reihenfolge ist frei wÃ¤hlbar. Nur eindeutige WidersprÃ¼che wie FunkgerÃ¤t â†’ FunkgerÃ¤t oder Antenne â†’ Antenne werden verhindert.","The order is freely selectable. Only clear contradictions such as radio â†’ radio or antenna â†’ antenna are prevented.")}</span></div>${routeBuilderHtml(r,i)}<button class=secondary data-addstep="${i}">${sysText("+ Anlagenteil","+ Device")}</button><div class="simple-route-check"><b>${sysText("PlausibilitÃ¤tsprÃ¼fung","Plausibility check")}</b>${topology}${status}${override}</div><button class=danger data-delroute="${i}">${t("deleteRoute")}</button></div>`}).join("");return `<div class="card simple-intro-card"><h2>${t("signalPaths")}</h2><p>${sysText("Baue den realen HF-Weg so auf, wie er bei dir tatsÃ¤chlich verschaltet ist. Du kannst mit FunkgerÃ¤t, PA, Tuner, Schalter oder auch einer Antenne beginnen; die Software zwingt keine kÃ¼nstliche Richtung auf.","Build the actual RF path exactly as it is wired in your station. You may start with a radio, PA, tuner, switch or even an antenna; the software does not impose an artificial direction.")}</p></div>${routes}<button id=addRoute class="primary-add">${t("addRoute")}</button>`}
function bindRoutes(){
 $$('[data-route][data-rk]').forEach(e=>e.onchange=()=>{let r=shared.routes[+e.dataset.route];if(!r)return;let k=e.dataset.rk,v=e.type==="checkbox"?e.checked:e.value;if(k==="bandOverride"&&v&&routeBandState(r).kind==="conflict"&&!confirm(t("overrideConfirm"))){e.checked=false;return}r[k]=v;renderTab();scheduleSharedSave()});
 $$('[data-route][data-step]').forEach(e=>e.onchange=()=>{let r=shared.routes[+e.dataset.route];if(!r)return;r.deviceKeys[+e.dataset.step]=e.value;renderTab();scheduleSharedSave()});
 $$('[data-addstep]').forEach(b=>b.onclick=()=>{let r=shared.routes[+b.dataset.addstep];if(!r)return;let step=(r.deviceKeys||[]).length,dev=allLogicalDevices().find(d=>routeCandidateAllowed(r,step,d));if(!dev)return toast(sysText("Kein weiteres passendes Anlagenteil verfÃ¼gbar.","No additional suitable system device is available."));r.deviceKeys.push(dev.key);renderTab();scheduleSharedSave()});
 $$('[data-delstep]').forEach(b=>b.onclick=()=>{let [ri,si]=b.dataset.delstep.split(',').map(Number),r=shared.routes[ri];if(!r)return;r.deviceKeys.splice(si,1);renderTab();scheduleSharedSave()});
 $$('[data-stepup]').forEach(b=>b.onclick=()=>{let [ri,si]=b.dataset.stepup.split(',').map(Number),r=shared.routes[ri];if(!r||si<=0)return;[r.deviceKeys[si-1],r.deviceKeys[si]]=[r.deviceKeys[si],r.deviceKeys[si-1]];renderTab();scheduleSharedSave()});
 $$('[data-stepdown]').forEach(b=>b.onclick=()=>{let [ri,si]=b.dataset.stepdown.split(',').map(Number),r=shared.routes[ri];if(!r||si>=r.deviceKeys.length-1)return;[r.deviceKeys[si+1],r.deviceKeys[si]]=[r.deviceKeys[si],r.deviceKeys[si+1]];renderTab();scheduleSharedSave()});
 $$('[data-delroute]').forEach(b=>b.onclick=()=>{let r=shared.routes[+b.dataset.delroute];if(!r)return;if(!confirm(`${t("deleteRoute")}: ${r.label||r.id}?`))return;shared.routes.splice(+b.dataset.delroute,1);renderTab();scheduleSharedSave()});
 if($('#addRoute'))$('#addRoute').onclick=()=>{let n=1,id=`route${n}`;while(shared.routes.some(r=>r.id===id))id=`route${++n}`;let palette=["#3f8fd2","#31a36c","#c5872b","#9859c7","#d25555","#2aa4a8"];shared.routes.push({id,label:(lang()==="en"?"Connection ":"Verbindung ")+n,color:palette[(n-1)%palette.length],deviceKeys:[],enabled:true,bandOverride:false,overrideNote:""});renderTab();scheduleSharedSave()};
}


const tabs=[["device","device"],["hardware","hardware"],["devices","devices"],["routes","routes"],["layout","layout"],["network","network"],["services","services"],["news","news"],["security","security"],["update","update"]];
async function loadConfig(){try{if(!configTarget)configTarget=combined.controllers?.find(c=>c.online)?.controllerId||"";[local,shared,boardData]=await Promise.all([api(`/api/controller/config?id=${encodeURIComponent(configTarget)}`),api("/api/shared"),api("/api/board")]);applyStatic();renderTabs();renderTab()}catch(e){toast(e.message)}}
function renderTabs(){
 if(currentTab==="functions")currentTab="devices";
 let online=(combined.controllers||[]).filter(c=>c.online);
 let targets=online.map(c=>`<option value="${c.controllerId}" ${c.controllerId===configTarget?"selected":""}>${c.self?t("clusterSelf")+" Â· ":""}${esc(c.callSign||"")} Â· ${esc(c.displayName||c.name)} Â· ${esc(c.ip||"â€”")}</option>`).join("");
 let cur=(combined.controllers||[]).find(c=>c.controllerId===configTarget)||{};
 $("#tabs").innerHTML=`<div class="config-target"><span>${t("currentTarget")}</span><strong>${cur.self?t("clusterSelf"):t("clusterRemote")}</strong><span>${esc(cur.callSign||"")}</span><span>${esc(cur.displayName||cur.name||"")}</span><span>${esc(cur.ip||"â€”")}</span></div><select id="configTarget">${targets}</select>`+tabs.map(([id,k])=>`<button class="${id===currentTab?"active":""}" data-tab="${id}">${t(k)}</button>`).join("");
 $("#configTarget").onchange=async e=>{await flushLocalSave();configTarget=e.target.value;await loadConfig()};
 $$("#tabs button").forEach(b=>b.onclick=()=>{currentTab=b.dataset.tab;renderTabs();renderTab()});
}
function field(label,path,val,type="text",extra=""){return `<label>${label}<input data-path="${path}" type="${type}" value="${esc(val??"")}" ${extra}></label>`}
function check(label,path,val){return `<label class="row"><input data-path="${path}" type="checkbox" ${val?"checked":""}> ${label}</label>`}
function setPath(o,p,v){let a=p.split("."),q=o;for(let i=0;i<a.length-1;i++)q=q[a[i]];q[a.at(-1)]=v}
function bindInputs(){$$("[data-path]").forEach(el=>el.onchange=async()=>{let v=el.type==="checkbox"?el.checked:el.type==="number"?Number(el.value):el.value;if(el.dataset.path==="txInterlock.activeHigh")v=el.value==="true";if(el.dataset.path==="txInterlock.gpio")v=Number(el.value);if(el.dataset.path.startsWith("shared.")){setPath(shared,el.dataset.path.slice(7),v);scheduleSharedSave()}else{setPath(local,el.dataset.path,v);scheduleLocalSave(el.dataset.path==="language"?0:300);if(el.dataset.path==="language"){await flushLocalSave();location.reload();return}}})}

