function ensureCustomBoard(){
 if(!local.customBoard)local.customBoard={name:t("customBoard"),note:t("customBoardWarning"),pins:[]};
 if(!Array.isArray(local.customBoard.pins))local.customBoard.pins=[];
 return local.customBoard;
}
function customPinClass(p){if(p.kind==="power")return "power";if(p.kind==="ground")return "ground";if(p.kind==="control")return "control";if(p.kind==="nc")return "forbidden";if(p.reserved)return "forbidden";if(p.digitalOutput)return p.strapping?"caution":"recommended";if(p.digitalInput||p.analogInput)return "input";return "forbidden"}
