 let rows=c.pins.map((p,i)=>`<tr><td><input data-cpi="${i}" data-cpk=label value="${esc(p.label||"")}"></td><td><select data-cpi="${i}" data-cpk=kind><option value=gpio ${p.kind==="gpio"?"selected":""}>${t("gpioKind")}</option><option value=power ${p.kind==="power"?"selected":""}>${t("powerKind")}</option><option value=ground ${p.kind==="ground"?"selected":""}>${t("groundKind")}</option><option value=control ${p.kind==="control"?"selected":""}>${t("controlKind")}</option><option value=nc ${p.kind==="nc"?"selected":""}>${t("ncKind")}</option></select></td><td><input data-cpi="${i}" data-cpk=gpio type=number min=-1 max=99 value="${Number(p.gpio??-1)}" ${p.kind!=="gpio"?"disabled":""}></td><td class=custom-flags>${["digitalInput","digitalOutput","analogInput","pullUp","pullDown","strapping","reserved"].map(k=>`<label><input data-cpi="${i}" data-cpk="${k}" type=checkbox ${p[k]?"checked":""} ${p.kind!=="gpio"?"disabled":""}> ${t(k)}</label>`).join("")}<label>${t("adcUnit")}<select data-cpi="${i}" data-cpk=adcUnit ${p.kind!=="gpio"?"disabled":""}><option value=0 ${!Number(p.adcUnit)?"selected":""}>â€”</option><option value=1 ${Number(p.adcUnit)===1?"selected":""}>ADC1</option><option value=2 ${Number(p.adcUnit)===2?"selected":""}>ADC2</option></select></label></td><td><select data-cpi="${i}" data-cpk=side><option value=left ${p.side!=="right"?"selected":""}>${t("left")}</option><option value=right ${p.side==="right"?"selected":""}>${t("right")}</option></select><label class=small>${t("pinOrder")}<input data-cpi="${i}" data-cpk=order type=number min=0 max=99 value="${Number(p.order??i)}"></label></td><td><textarea data-cpi="${i}" data-cpk=note rows=3>${esc(p.note||"")}</textarea></td><td><button class=danger data-delcp="${i}">Ã—</button></td></tr>`).join("");
 return `<div class="card custom-board-card"><h2>${t("customBoard")}</h2><div class="custom-warning">âš  ${t("customBoardWarning")}<br>${t("customResponsibility")}</div><div class=grid2><label>${t("customBoardName")}<input data-cb=name value="${esc(c.name||"")}"></label><label>${t("customBoardNote")}<input data-cb=note value="${esc(c.note||"")}"></label></div><div class="custom-copy row"><label>${t("copyProfile")}<select id=copyBoardSource>${sources}</select></label><button id=copyBoard class=secondary>${t("copyNow")}</button><button id=clearCustomPins class=danger>${t("emptyProfile")}</button><button id=deleteCustomBoard class=danger>${sysText("Profil lÃ¶schen","Delete profile")}</button></div><div class=table-scroll><table class="table custom-pin-table"><thead><tr><th>${t("pinLabel")}</th><th>${t("pinKind")}</th><th>${t("gpioPin")}</th><th>${t("pinCapabilities")}</th><th>${t("pinSide")}</th><th>${t("pinNoteOwn")}</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan=7 class=small>${t("customEmpty")}</td></tr>`}</tbody></table></div><button id=addCustomPin>${t("addPin")}</button></div>`;
