function copyBuiltinToCustom(id){let b=(boardData.profiles||[]).find(x=>x.id===id);if(!b)return;let c=ensureCustomBoard();c.name=`${boardLabel(b)} Â· ${t("copySuffix")}`;c.note=t("customBoardWarning");c.pins=(b.pins||[]).map((p,i)=>{let note=p.noteEn||p.note||"",cls=p.class||"forbidden",kind=cls==="power"?"power":cls==="ground"?"ground":cls==="control"?"control":(cls==="forbidden"&&p.gpio===undefined)?"nc":"gpio";return{label:p.label||`Pin ${i+1}`,gpio:p.gpio??-1,kind,digitalInput:["recommended","caution","input"].includes(cls),digitalOutput:["recommended","caution"].includes(cls),analogInput:/ADC[12]/i.test(note),adcUnit:/ADC1/i.test(note)?1:/ADC2/i.test(note)?2:0,pullUp:/pull-up/i.test(note),pullDown:/pull-down/i.test(note),strapping:/strapping/i.test(note),reserved:cls==="forbidden",side:p.side==="right"?"right":"left",order:Number(p.order??i),note:pinNote(p)||""}})}
function firstFreeCustomGpio(){let used=new Set(ensureCustomBoard().pins.filter(p=>p.kind==="gpio").map(p=>Number(p.gpio)));for(let g of [18,19,21,22,23,25,26,27,32,33,34,35,36,39,4,13,14,16,17])if(!used.has(g))return g;for(let g=0;g<40;g++)if(!used.has(g))return g;return -1}

