 let newRows=discovered.map(c=>{let relation=c.relation==="unassigned"?sysText("NEU / NICHT ZUGEORDNET","NEW / UNASSIGNED"):sysText("Andere Anlage","Other system"),actions="";if(isMaster&&c.relation==="unassigned"){let disabled=sys.admissionMode==="off"?"disabled":"";actions=`<div class="new-controller-actions"><button data-adopt="${esc(c.controllerId)}" ${disabled}>${sysText("Zu dieser Anlage hinzufÃ¼gen","Add to this system")}</button><button class=secondary data-own-master="${esc(c.controllerId)}" ${disabled}>${sysText("Als neue eigene Anlage einrichten","Make separate master")}</button><button class=secondary data-ignore-new="${esc(c.controllerId)}">${sysText("SpÃ¤ter entscheiden","Decide later")}</button></div>`}return `<div class="new-controller-card ${c.relation==="foreign"?"foreign":""}"><div><b>${esc(c.name||sysText("Neuer Controller","New controller"))}</b> Â· ${esc(c.callSign||"")} Â· ${esc(c.location||"â€”")}</div><div class=small>${relation}${c.relation==="foreign"&&c.systemName?` Â· ${esc(c.systemName)}`:""} Â· ${esc(c.ip||"â€”")}</div>${actions}</div>`}).join("");
