function newsHtml(){let rows=(local.news.feeds||[]).map((f,i)=>`<tr><td><input data-ni="${i}" data-nk=enabled type=checkbox ${f.enabled?"checked":""}></td><td><input data-ni="${i}" data-nk=name value="${esc(f.name)}"></td><td><select data-ni="${i}" data-nk=language><option value=de ${f.language==="de"?"selected":""}>DE</option><option value=en ${f.language==="en"?"selected":""}>EN</option></select></td><td><input data-ni="${i}" data-nk=url value="${esc(f.url)}"></td><td><button class=danger data-deln="${i}">Ã—</button></td></tr>`).join("");return `<div class=card><h2>${t("hamNews")}</h2>${check(t("newsActive"),"news.enabled",local.news.enabled)}<div class=grid3><label>${t("newsLanguage")}<select data-path=news.language><option value=de ${local.news.language==="de"?"selected":""}>${t("german")}</option><option value=en ${local.news.language==="en"?"selected":""}>${t("english")}</option></select></label>${field(t("refreshMinutes"),"news.refreshMinutes",local.news.refreshMinutes,"number",'min="30" max="1440"')}${field(t("maxItems"),"news.maxItems",local.news.maxItems,"number",'min="1" max="10"')}</div><div class=table-scroll><table class=table><thead><tr><th>${t("active")}</th><th>${t("name")}</th><th>${t("language")}</th><th>${t("feedUrl")}</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><div class="news-config-actions"><button id=addFeed>${t("addFeed")}</button></div><div id=newsStatus class="news-status small">${t("newsStarting")}</div><p class=small>${t("newsInfo")}</p></div>`}
function bindNews(){bindInputs();$$("[data-ni]").forEach(e=>e.onchange=()=>{let f=local.news.feeds[+e.dataset.ni],k=e.dataset.nk;f[k]=e.type==="checkbox"?e.checked:e.value;scheduleLocalSave()});$$("[data-deln]").forEach(b=>b.onclick=()=>{local.news.feeds.splice(+b.dataset.deln,1);renderTab();scheduleLocalSave()});$("#addFeed").onclick=()=>{local.news.feeds.push({id:"feed"+Date.now(),name:lang()==="en"?"New source":"Neue Quelle",language:local.news.language,url:"",enabled:true});renderTab();scheduleLocalSave()};setTimeout(async()=>{try{let n=await api("/api/news"),e=$("#newsStatus");if(e)e.textContent=n.fetching?t("fetching"):n.lastError?`${t("lastFetch")}: ${n.lastError}`:n.items?.length?`${n.items.length} ${t("loaded")}`:t("noFetch")}catch{}},150)}

async function loadDiag(){try{let [snap,errs,peers]=await Promise.all([api("/api/snapshot"),api("/api/errors"),api("/api/peers")]);let role=snap.temporaryCoordinator?sysText("Follower Â· ERSATZMASTER AKTIV","Follower Â· REPLACEMENT MASTER ACTIVE"):snap.reclaiming?sysText("MASTER Â· synchronisiert","MASTER Â· synchronizing"):roleText(snap.systemRole||combined.system?.role||"unassigned");$("#diagBody").innerHTML=`<div class=card><h2>${t("system")}</h2><div class=grid3><div>${sysText("Rolle","Role")}<br><b>${role}</b></div><div>${t("firmware")}<br><b>v${esc(snap.firmwareVersion||"?")}</b></div><div>${t("build")}<br><b>${esc(formatBuildDate(snap.buildDate||""))}</b></div><div>${t("ip")}<br><b>${esc(snap.ip)}</b></div><div>RSSI<br><b>${snap.rssi} dBm</b></div><div>${t("freeHeap")}<br><b>${snap.heap} B</b></div><div>${t("time")}<br><b>${snap.timeSynced?t("synchronized"):t("notSynchronized")}</b></div><div>${t("uptime")}<br><b>${Math.floor(snap.uptimeMs/1000)} s</b></div><div>ESP-IDF/SDK<br><b>${esc(snap.sdk||"")}</b></div><div>${t("resetReason")}<br><b>${snap.resetReason}</b></div></div></div><div class=card><h2>${t("cluster")}</h2>${peers.length?peers.map(p=>`<div>${esc(p.callSign||"")} Â· ${esc(p.name)} Â· ${esc(p.location||"â€”")} Â· ${esc(p.ip)} Â· v${esc(p.firmware||"?")} Â· <span class=${p.online?"online":"offline"}>${t(p.online?"online":"offline")}</span></div>`).join(""):t("noPeer")}</div><div class=card><h2>${t("errorStore")} (${errs.length}/10)</h2>${errs.length?errs.map(e=>`<div class=err><b>${esc(e.code)}</b> ${esc(e.text)}</div>`):`<p>${t("systemOk")}</p>`}<button id=clearErr class=danger>${t("clearErrors")}</button></div>`;$("#clearErr").onclick=async()=>{await api("/api/errors",{method:"DELETE"});loadDiag()}}catch(e){toast(e.message)}}
