$("#stopAll").onclick=async()=>{if(confirm(t("allOffAsk"))){try{let r=await post("/api/stop",{});if(r.scope==="system"&&!r.complete){let failed=(r.nodes||[]).filter(n=>!n.ok).map(n=>n.name||n.ip).filter(Boolean).join(", ");alert(sysText(`NOT-AUS unvollstÃ¤ndig. Mindestens ein SteuergerÃ¤t hat die Abschaltung nicht bestÃ¤tigt.${failed?" Nicht bestÃ¤tigt: "+failed:""}`,`EMERGENCY OFF incomplete. At least one controller did not confirm shutdown.${failed?" Not confirmed: "+failed:""}`))}else toast(r.scope==="system"?sysText("Alle erreichbaren SteuergerÃ¤te AUS bestÃ¤tigt","All reachable controllers confirmed OFF"):sysText("Lokaler STOP ausgefÃ¼hrt","Local STOP executed"));await refresh()}catch(e){toast(e.message)}}};
function downloadJson(name,obj){let blob=new Blob([JSON.stringify(obj,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function updateHtml(){let self=(combined.controllers||[]).find(c=>c.self)||{},version=self.firmware||self.firmwareVersion||"";return `<div class="card update-safety-card"><h2>${sysText("Programm / Update","Program / Update")}</h2><div class="update-warning"><b>${sysText("Sicherheitsregel: Kein Update ohne Sicherung","Safety rule: no update without a backup")}</b><p>${sysText("Vor jeder Programmaktualisierung erzeugt der ESP automatisch eine geprÃ¼fte Sicherung seiner lokalen und gemeinsamen Konfiguration einschlieÃŸlich WLAN-Zustand.","Before every firmware update the controller automatically creates a verified backup of local/shared configuration including Wi-Fi state.")}</p></div><div class="update-facts"><span><b>${sysText("Aktuelle Version","Current version")}</b>${esc(version||"-")}</span><span><b>${sysText("Update-Quelle","Update source")}</b>https://github.com/zentrog/ESP32-Antennenschalter-Produkt/releases/latest</span></div>${check(sysText("Programmaktualisierung erlauben","Allow firmware updates"),"features.ota",local.features.ota)}<div id=onlineUpdateState class="online-update-state">${sysText("OnlineprÃ¼fung noch nicht ausgefÃ¼hrt.","Online check not run yet.")}</div><div class="update-actions"><button id=checkOnlineUpdate class=secondary>${sysText("Online nach Update suchen","Check online for update")}</button><button id=openReleasePage class=secondary>${sysText("Downloadseite Ã¶ffnen","Open download page")}</button><button id=downloadUpdateBackup class=secondary>${sysText("Sicherheitskopie herunterladen","Download safety backup")}</button><button id=openUpdatePage class=secondary ${local.features.ota?"":"disabled"}>${sysText("Manuelles OTA Ã¶ffnen","Open manual OTA")}</button></div><p class="small">${sysText("Die OnlineprÃ¼fung informiert Ã¼ber freigegebene stabile Versionen. Eine Installation wird niemals ohne bewusste Benutzeraktion gestartet. Das manuelle OTA bleibt als RÃ¼ckfallebene erhalten.","The online check announces released stable versions. Installation is never started without explicit user action. Manual OTA remains available as a fallback.")}</p></div>`}
async function bindUpdate(){bindInputs();let renderOnline=u=>{let e=$("#onlineUpdateState");if(!e)return;if(u?.error){e.className="online-update-state error";e.textContent=u.error;return}if(!u)return;e.className=`online-update-state ${u.available?"available":"current"}`;e.innerHTML=u.available?`<b>${sysText("Neue Version verfÃ¼gbar","New version available")}: ${esc(u.latest||"?")}</b>${u.notes?`<span>${u.notes}</span>`:""}`:`<b>${sysText("Installierte Version ist aktuell","Installed version is current")}: ${esc(u.current||"")}</b>`};let check=async()=>{let e=$("#onlineUpdateState");if(e)e.textContent=sysText("PrÃ¼fe GitHub Releases â€¦","Checking GitHub Releases â€¦");try{renderOnline(await api("/api/update/check"))}catch(x){renderOnline({error:x.message})}};if($("#checkOnlineUpdate"))$("#checkOnlineUpdate").onclick=check;if($("#openReleasePage"))$("#openReleasePage").onclick=()=>window.open("https://github.com/zentrog/ESP32-Antennenschalter-Produkt/releases/latest","_blank","noopener");if($("#downloadUpdateBackup"))$("#downloadUpdateBackup").onclick=async()=>{try{await flushLocalSave();if(sharedDirty||savingShared)await saveSharedNow();location.href="/api/update-backup"}catch(e){toast(e.message)}};if($("#openUpdatePage"))$("#openUpdatePage").onclick=async()=>{try{await flushLocalSave();if(sharedDirty||savingShared)await saveSharedNow();window.open("/update","_blank","noopener")}catch(e){toast(e.message)}};setTimeout(check,200)}
function bindSecurity(){if($("#saveSecurity"))$("#saveSecurity").onclick=async()=>{let enabled=$("#adminEnable").checked,user=$("#adminUser").value.trim()||"admin",pw=$("#adminPass").value;shared.security=shared.security||{};shared.security.adminAuthEnabled=enabled;shared.security.adminUser=user;shared.security.adminPassword=pw;markSharedDirty();try{await saveSharedNow();toast(sysText("Anlagenschutz gespeichert","System protection saved"));if(pw)$("#adminPass").value=""}catch(e){toast(e.message)}};$("#backupBtn").onclick=async()=>{try{await flushLocalSave();if(sharedDirty||savingShared)await saveSharedNow();location.href="/api/update-backup"}catch(e){toast(e.message)}};$("#restoreBtn").onclick=()=>$("#restoreFile").click();$("#restoreFile").onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let b=JSON.parse(await f.text()),ok=(b.format==="AntennaControllerBackupV1"||b.format==="AntennaControllerSafetyBackupV2")&&b.local&&b.shared;if(!ok)throw Error(t("backupInvalid"));if(!confirm(t("backupAsk")))return;await post("/api/shared?force=1",b.shared,"PUT");await post(`/api/controller/config?id=${encodeURIComponent(configTarget)}&force=1`,b.local,"PUT");if(b.wifiState)await post("/api/wifi/restore",b.wifiState);toast(sysText("Sicherung vollstÃ¤ndig eingespielt.","Backup restored completely."))}catch(ex){toast(ex.message)}};$("#factoryBtn").onclick=async()=>{if(!confirm(t("factoryAsk")))return;try{await post(`/api/controller/factory-reset?id=${encodeURIComponent(configTarget)}`,{})}catch(e){toast(e.message)}}}

